public class Outer {
    private String tag = "outer";

    void run() {
        Runnable lambda = () -> System.out.println(tag);      // invokedynamic
        Runnable anon = new Runnable() {                       // new Outer$1()
            public void run() { System.out.println(tag); }
        };
        lambda.run();
        anon.run();
    }
}

// Sau khi javac biên dịch, thư mục đầu ra có:
//   Outer.class      (chứa cả method synthetic lambda$run$0)
//   Outer$1.class    (anonymous class)
// -> KHÔNG có file .class nào cho lambda

void demo(List<String> names) {
    int count = 0;
    names.forEach(n -> count++);          // LỖI BIÊN DỊCH: count không effectively final

    List<String> upper = new ArrayList<>();
    names.forEach(n -> upper.add(n.toUpperCase())); // OK: reference không đổi, nội dung đổi

    for (int i = 0; i < 3; i++) {
        Runnable r = () -> System.out.println(i);   // LỖI: i bị gán lại mỗi vòng
    }

    for (String s : names) {
        Runnable r = () -> System.out.println(s);   // OK: s là biến mới mỗi vòng lặp
    }
}

class Heavy {
    private final byte[] buffer = new byte[64 * 1024 * 1024];
    private int version = 7;

    // XẤU: lambda đọc field 'version' => capture this => giữ luôn buffer 64MB
    Supplier<Integer> leaky() {
        return () -> version;
    }

    // TỐT: copy ra biến local, lambda chỉ giữ một int
    Supplier<Integer> safe() {
        int snapshot = version;
        return () -> snapshot;
    }
}

class Outer {
    void demo() {
        Runnable lambda = () -> System.out.println(this);           // this = Outer
        Runnable anon = new Runnable() {
            public void run() {
                System.out.println(this);                            // this = Outer$1
                System.out.println(Outer.this);                      // muốn Outer phải viết rõ
            }
        };
    }
}

